function applyHomeCopy(code){if(!document.querySelector('.trust-section'))return;const d=ICA_HOME_COPY[code]||ICA_HOME_COPY.ko;const h=document.querySelector('.trust-section h2');if(h){h.childNodes.forEach(n=>{if(n.nodeType===Node.TEXT_NODE)n.textContent=d[0]});const gold=h.querySelector('.gold');if(gold)gold.textContent=d[1];const last=h.lastChild;if(last&&last.nodeType===Node.TEXT_NODE)last.textContent=d[2];}setText('.trust-section .trust-grid > div > p:not(.section-kicker)',d[3]);setText('#icaVerificationTitle',d[4]);document.querySelectorAll('.ica-entry-mega__links a').forEach((a,i)=>{if(d[5+i])a.textContent=d[5+i]});setText('a.skip',d[11]);}
function apply(code){const selected=code;code=code==='fil'?'tl':code;const d=T[code]||T.ko;document.documentElement.lang=code==='zh-CN'?'zh-CN':code;document.documentElement.dir=(code==='ar'||code==='fa')?'rtl':'ltr';const nav=document.querySelectorAll('.nav__item');if(nav.length>=6){nav[0].textContent=d.verify;nav[1].textContent=d.cert;nav[2].textContent=d.partners;nav[3].textContent=d.standards;nav[4].textContent=d.about;nav[5].textContent=d.contact}setText('.badge',d.registry);setText('.hero__lead',d.lead);setText('.quick-verify label',d.number);const input=document.querySelector('#quickCode');if(input)input.placeholder=d.placeholder;setText('.quick-verify button',d.button);setText('.language-link',d.available);setText('.service-section .section-kicker',d.services);setText('.service-section h2',d.servicesTitle);const cards=document.querySelectorAll('.service-card small');[d.s1,d.s2,d.s3,d.s4].forEach((x,i)=>{if(cards[i])cards[i].textContent=x});applyHomeCopy(code);localStorage.setItem('ica_language',selected);const u=new URL(location.href);if(code==='ko')u.searchParams.delete('lang');else u.searchParams.set('lang',code);history.replaceState(null,'',u.pathname+u.search+u.hash);panel.hidden=true;document.body.classList.remove('ica20-lock');document.querySelectorAll('.langbtn.ica20-open').forEach(b=>b.textContent='🌐 21 LANGUAGES');document.dispatchEvent(new CustomEvent('ica-language-change',{detail:{code}}))}
